INSERT INTO rectification_feedback (notice_id, enterprise_id, measures, after_images, after_videos, remark, check_type, attachment_urls, status) VALUES
(4, 1, '已完成全部4项问题整改：1.车间地面排水系统已修缮完毕新安装3个排水口;2.冷库温度记录系统已更换为自动记录仪数据实时上传;3.3名过期健康证人员已重新体检并取得新证;4.食品添加剂台账已按新模板重新登记', CAST('["/uploads/feedback/1/车间排水改造.jpg","/uploads/feedback/1/冷库自动记录仪.jpg","/uploads/feedback/1/新健康证.jpg","/uploads/feedback/1/添加剂台账.jpg"]' AS JSON), CAST('["/uploads/feedback/1/车间改造视频.mp4"]' AS JSON), '整改费用合计约2.3万元', '食品生产科', CAST('["/uploads/feedback/1/整改报告.pdf","/uploads/feedback/1/排水工程验收单.pdf"]' AS JSON), 'SUBMITTED'),
(2, 2, '已完成全部3项问题整改：1.消防通道杂物已全部清理设置通道标识和禁停线;2.所有商品已按规定离地15cm存放加装货架;3.2个过期灭火器已更换为新品并完成全库区8个灭火器检查', CAST('["/uploads/feedback/2/消防通道清理.jpg","/uploads/feedback/2/商品离地存放.jpg","/uploads/feedback/2/新灭火器.jpg"]' AS JSON), NULL, '整改费用合计约0.6万元', '商贸流通科', CAST('["/uploads/feedback/2/整改报告.pdf"]' AS JSON), 'SUBMITTED'),
(5, 3, '部分整改完成：1.2台叉车已重新办理使用登记证;2.压力容器安全阀已送校预计7月5日取回;3.操作人员已报名培训预计7月中旬取证;4.起重机械限位装置已更换新件并通过测试', CAST('["/uploads/feedback/3/叉车新登记证.jpg","/uploads/feedback/3/限位装置更换.jpg","/uploads/feedback/3/安全阀送校回执.jpg"]' AS JSON), CAST('["/uploads/feedback/3/限位装置测试.mp4"]' AS JSON), '安全阀校验和操作人员取证尚需时间预计7月15日前全部完成', '特种设备科', CAST('["/uploads/feedback/3/整改进度报告.pdf","/uploads/feedback/3/培训报名确认.pdf"]' AS JSON), 'SUBMITTED');
